KG42.register("edges-7ef46973c2ff9080c0863b2a",{"id":"S-7d6be3efa52b74fc","source":"COMP-b9841ac99d9d29b8","type":"links","target":"COMP-b3f649e90c1f17b9","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["12-p2p_microgrid_trading","17-exogenous_cost_allocation","43-operating_envelope_ev_market"],"assertions":[{"id":"12-p2p_microgrid_trading::v141-c-R007::E::v141-c-R007-E001","paper":"12-p2p_microgrid_trading","rule_id":"v141-c-R007","rule_ref":"12-p2p_microgrid_trading::v141-c-R007","record":{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R007-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b9841ac99d9d29b8","target":"COMP-b3f649e90c1f17b9","source_occurrence_id":"12-p2p_microgrid_trading::v141-c-R007::V::bidding.demand","target_occurrence_id":"12-p2p_microgrid_trading::v141-c-R007::V::bidding.supply","source_unit_id":"12-p2p_microgrid_trading::v141-a-M02::bidding.demand","target_unit_id":"12-p2p_microgrid_trading::v141-a-M02::bidding.supply","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Elecbay alternative seller-initiated order placement for half-hour energy requirements. | Elecbay publishing and bidding period. | Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. | Information contained in Elecbay supply orders. | Modification or cancellation of Elecbay supply orders after gate closure. | Peer-initiated placement, cancellation and modification of Elecbay supply orders.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-15","v141-b-g01-ev-21","v141-b-g01-ev-23","v141-b-g01-ev-24"]},"active":true,"source_signature":"3bd95abc04ce94588f4edd96b796690ffa583b00731694b8e639185a91c05fb3","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M02","source_definition":"Peers may list the energy required over half an hour for purchase and place demand orders. Scope: Elecbay requested-energy listings and purchase orders for half-hourly energy exchanges. Condition: During the publishing and bidding time period. Each demand order contains the energy-exchange time period, amount, price and seller and buyer details. Identities and energy-supply reliability ratings are examples of those details. Scope: Information contained in demand orders placed on Elecbay. Peers may place, cancel or modify demand orders only before gate closure, which is one hour before the energy-exchange period in this paper. Scope: Placement, cancellation and modification of Elecbay demand orders by peers. Only DSOs have permission to modify or cancel demand orders after gate closure under this condition. Scope: Modification or cancellation of Elecbay demand orders after gate closure. Condition: A network constraint violation has been identified. Demand orders placed later, closer to gate closure, have a higher possibility of cancellation. Scope: Illustrative Elecbay order-cancellation policy, not an assertion that this policy was adopted. Condition: If the example last on first off principle is applied.","target_definition":"Buyers' demand submissions provide the listed half-hour energy requirements that sellers browse when placing supply orders. Scope: Elecbay alternative seller-initiated order placement for half-hour energy requirements. Condition: When sellers browse items listed by energy buyers and place orders against those requirements. Peers may list their surplus energy over half an hour for sale and place supply orders. Scope: Elecbay publishing and bidding period. Condition: During the publishing and bidding time period. Each supply order contains the energy-exchange time period, energy quantity, energy price, and seller and buyer details, including identities and energy-supply reliability ratings. Scope: Information contained in Elecbay supply orders. Peers may place, cancel or modify supply orders only before gate closure. Scope: Peer-initiated placement, cancellation and modification of Elecbay supply orders. Condition: Before gate closure, which is one hour before the energy exchange time period in this paper. DSOs alone have permission to modify or cancel supply orders in this condition. Scope: Modification or cancellation of Elecbay supply orders after gate closure. Condition: After gate closure, once a network constraint violation has been identified. Supply orders placed later, closer to gate closure, have a higher possibility of cancellation. Scope: Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. Condition: If the example last on first off principle is used.","constraints":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"Buyers' demand submissions provide the listed half-hour energy requirements that sellers browse when placing supply orders. Scope: Elecbay alternative seller-initiated order placement for half-hour energy requirements. Condition: When sellers browse items listed by energy buyers and place orders against those requirements.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-14","location":{"location_id":"src-c1934be9b4-p04-c1r2__v141-a-M02-bidding","page":4,"printed_page":null,"section":"3. Platform for Peer-to-Peer energy trading","anchor_text":"Order Pre-payment Fig. 2. Interactions of key players d the information including the time period fo","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each order contains the information including the time period for the energy exchange, the amount of energy to be exchanged, the price of the energy to be exchanged and the details about the seller and buyer, e.g. the identities, the ratings of energy supply reliability, etc."},{"evidence_id":"v141-b-g01-ev-15","location":{"location_id":"src-c1934be9b4-p04-c1r2__v141-a-M02-bidding","page":4,"printed_page":null,"section":"3. Platform for Peer-to-Peer energy trading","anchor_text":"Order Pre-payment Fig. 2. Interactions of key players d the information including the time period fo","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Alternatively, energy sellers can also browse the items listed by energy buyers, i.e. the required energy over half an hour, and then place orders."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Elecbay alternative seller-initiated order placement for half-hour energy requirements. | Elecbay publishing and bidding period. | Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. | Information contained in Elecbay supply orders. | Modification or cancellation of Elecbay supply orders after gate closure. | Peer-initiated placement, cancellation and modification of Elecbay supply orders.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14","v141-b-g01-ev-15","v141-b-g01-ev-21","v141-b-g01-ev-23","v141-b-g01-ev-24"]},"source_record":{"edge_id":"v141-c-R007-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-ev-14","v141-b-g01-ev-15"]},"paper_scope_note":"Buyer order placement and seller order placement are alternative processes; payment to the platform and the platform's distribution of bills are not the same data object; temporal order only preserves the source fact."}},{"id":"17-exogenous_cost_allocation::v141-c-R002::E::v141-c-R002-E001","paper":"17-exogenous_cost_allocation","rule_id":"v141-c-R002","rule_ref":"17-exogenous_cost_allocation::v141-c-R002","record":{"edge_id":"v141-c-R002-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e17","v141-b-g01-e20"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R002-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b9841ac99d9d29b8","target":"COMP-b3f649e90c1f17b9","source_occurrence_id":"17-exogenous_cost_allocation::v141-c-R002::V::bidding.demand","target_occurrence_id":"17-exogenous_cost_allocation::v141-c-R002::V::bidding.supply","source_unit_id":"17-exogenous_cost_allocation::v141-M01::bidding.demand","target_unit_id":"17-exogenous_cost_allocation::v141-M01::bidding.supply","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Bilateral offered-quantity updates by prosumers in (6a). | Consumer quantity proposals in the decentralized update (6a). | Offered-quantity components of participant updates in the decentralized negotiation mechanism (6). | Offered-quantity components of the decentralized bilateral negotiation update (6a). | Permissible bilateral offered quantities in the P2P trading partnership structure. | Power feasibility of offered-quantity updates in (6a), at every iteration. | Submission of offered-quantity components during each decentralized negotiation iteration.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e09","v141-b-g01-e10","v141-b-g01-e17","v141-b-g01-e18","v141-b-g01-e20"]},"active":true,"source_signature":"94bf2170604b07fbad852789ff10594f1d52062a25827ca398342e142ea984fe","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-M01","source_definition":"The trading partnership set restricts demand proposals: the bilateral quantity must be zero for a counterparty outside that set. Scope: Buying-side trade proposals in the decentralized P2P negotiation. Condition: When a prospective counterparty is outside the requesting agent's trading partnership set. Current bilateral trade-price signals enter the participant's optimization that updates its requested energy quantities. Scope: Buying-side quantity updates in the decentralized consensus-ADMM negotiation of (6). Condition: At each negotiation iteration. Participants update requested quantities through their own optimization (6a) and individually send the resulting trade proposals to their trading partners; the negotiation process repeats until convergence. Scope: Submission of buying-side trade proposals in the decentralized P2P negotiation. Condition: During each iteration of the negotiation process, until convergence. Requested quantities must be updated consistently with the agent's total-power bounds, with total power equal to the sum of its bilateral proposals. Scope: Requested-power updates in (6a), jointly with the agent's other bilateral proposals. Condition: At every negotiation iteration. Each prosumer's requested bilateral quantity must remain within that prosumer's power boundaries. Scope: Individual buying-side bilateral proposals in the update (6a). Condition: When the requesting agent is a prosumer. The prescribed update prohibits buying requests from generators by constraining their bilateral proposed quantities to be nonnegative. Scope: Bilateral quantity proposals produced by the update (6a). Condition: When the updating agent is a generator.","target_definition":"The partner's previous requested quantity enters the averaging and penalty terms used to update the offered quantity. Scope: Offered-quantity components of the decentralized bilateral negotiation update (6a). Condition: The partner counterproposal represents requested power. The previous bilateral trade-price signals enter the participant's optimization that updates its offered quantities, economically encouraging consensus with its partners. Scope: Offered-quantity components of participant updates in the decentralized negotiation mechanism (6). The trading partnership set restricts possible supply offers: the bilateral quantity to a counterparty outside that set must be zero. Scope: Permissible bilateral offered quantities in the P2P trading partnership structure. Condition: Agent m is outside agent n's trading partnership set. The participant sends its updated offered quantities to the corresponding trading partners. Scope: Submission of offered-quantity components during each decentralized negotiation iteration. Condition: After the participant has updated its trade proposals through its own optimization (6a). When updating offered quantities, the participant's total power, summed across all its bilateral proposals, must remain within its lower and upper power bounds. Scope: Power feasibility of offered-quantity updates in (6a), at every iteration. Each bilateral offered quantity must also lie within the prosumer's individual power boundaries. Scope: Bilateral offered-quantity updates by prosumers in (6a). Condition: The submitting participant belongs to the prosumer set. Consumers cannot submit positive selling quantities: their bilateral proposal quantities must be nonpositive. Scope: Consumer quantity proposals in the decentralized update (6a). Condition: The submitting participant belongs to the consumer set.","constraints":[{"constraint_id":"v141-c-R002-C001","kind":"mathematical","role":"core","statement":"The partner's previous requested quantity enters the averaging and penalty terms used to update the offered quantity. Scope: Offered-quantity components of the decentralized bilateral negotiation update (6a). Condition: The partner counterproposal represents requested power.","expression":"\\lambda_{nm}^{k}\\left(\\frac{p_{nm}^{k}-p_{mn}^{k}}{2}-p_{nm}\\right)+\\frac{\\rho}{2}\\left(\\frac{p_{nm}^{k}-p_{mn}^{k}}{2}-p_{nm}\\right)^2","formalization_origin":"source","template_id":null,"members":["bidding.demand","bidding.supply"],"variable_refs":["v141-c-R002-x-p-nm"],"parameter_refs":["v141-c-R002-theta-p-mn-k","v141-c-R002-theta-lambda-nm-k","v141-c-R002-theta-rho"],"evidence_ids":["v141-b-g01-e17","v141-b-g01-e20"]}],"evidence":[{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-12e1fd7a17-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"a competitive equilibrium which efﬁciency strongly depends on w the chosen network charges. Accordin","equation_id":"Eq. (6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As developed in Appendix B, a decentralized procedure based on the consensus ADMM of [11] is used to solve (5). This decentralized method solves global problem (5) and, hence, leads to a competitive equilibrium which efficiency strongly depends on the chosen network charges. According to [19] ADMM seems well adapted for negotiation mechanisms in smart grids. Several extensions and convergence rate improvements have been proposed in [20]–[23]. Given the focus of this paper is not on scalability a straightforward implementation of consensus ADMM is used. The final decentralized negotiation mechanism reads P_n^{k+1}=\\arg\\min_{P_n} f_n(p_n)+\\gamma_n^0+\\sum_{m\\in\\omega_n}\\left[\\gamma_{nm}p_{nm}+\\lambda_{nm}^k\\left(\\frac{p_{nm}^k-p_{mn}^k}{2}-p_{nm}\\right)+\\frac{\\rho}{2}\\left(\\frac{p_{nm}^k-p_{mn}^k}{2}-p_{nm}\\right)^2\\right] (6a); s.t. p_n=\\sum_{m\\in\\omega_n}p_{nm}; \\underline{p}_n\\le p_n\\le\\overline{p}_n; p_{nm}\\ge0 \\text{ if } n\\in\\Omega_g; p_{nm}\\le0 \\text{ if } n\\in\\Omega_c; \\underline{p}_n\\le p_{nm}\\le\\overline{p}_n \\text{ if } n\\in\\Omega_p (6a); \\lambda_{nm}^{k+1}=\\lambda_{nm}^k-\\rho(p_{nm}^{k+1}+p_{mn}^{k+1})/2 (6b)."},{"evidence_id":"v141-b-g01-e20","location":{"location_id":"src-12e1fd7a17-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"II. P2P Market Design","anchor_text":"on with (8). Finally, each agent n broadcasts its local residuals to ms all and, when all local resi","equation_id":"Eq. (6)-(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The overall negotiation mechanism occurs as follows. Each market participant first solves its own local optimization (6a). Once updated, each agent n individually sends its trade proposals (p_{nm}^{k+1})_{m\\in\\omega} to each partner m\\in\\omega_n. After receiving all counter proposals (p_{mn}^{k+1})_{m\\in\\omega}, agent n can compute its new trade prices (\\lambda_{nm}^{k+1})_{m\\in\\omega} with (6b), and local residuals (r_n,s_n)^{k+1} with (8). Finally, each agent n broadcasts its local residuals to all and, when all local residuals (r_i,s_i)^{k+1}_{i\\in\\Omega\\setminus\\{n\\}} are received, tests global stopping criteria (7). This process is repeated until convergence. Being decentralized the negotiation mechanism is not supported by a central entity. However, as most information exchanges, a communication standard needs to be defined by an institutional organization to associate a communication protocol between peers participating in the market."}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Bilateral offered-quantity updates by prosumers in (6a). | Consumer quantity proposals in the decentralized update (6a). | Offered-quantity components of participant updates in the decentralized negotiation mechanism (6). | Offered-quantity components of the decentralized bilateral negotiation update (6a). | Permissible bilateral offered quantities in the P2P trading partnership structure. | Power feasibility of offered-quantity updates in (6a), at every iteration. | Submission of offered-quantity components during each decentralized negotiation iteration.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e09","v141-b-g01-e10","v141-b-g01-e17","v141-b-g01-e18","v141-b-g01-e20"]},"source_record":{"edge_id":"v141-c-R002-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e17","v141-b-g01-e20"]},"paper_scope_note":"The bilateral negotiated price update and the exogenous network fee signal are separately limited in meaning; partner-set constraints, incentive intent, and ADMM computational dependencies cannot be transmitted in a mixed way."}},{"id":"43-operating_envelope_ev_market::v141-c-R004::E::v141-c-R004-E001","paper":"43-operating_envelope_ev_market","rule_id":"v141-c-R004","rule_ref":"43-operating_envelope_ev_market::v141-c-R004","record":{"edge_id":"v141-c-R004-E001","source":"bidding.demand","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g02-E31","v141-b-g02-E33","v141-b-g03-e011"]},"evidence_class":"S","provenance_gate":"direct_C_edge_user_admitted","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R004-C001"],"held_constraint_ids":[],"semantic_review_status":"user_admitted_direct_source","source":"COMP-b9841ac99d9d29b8","target":"COMP-b3f649e90c1f17b9","source_occurrence_id":"43-operating_envelope_ev_market::v141-c-R004::V::bidding.demand","target_occurrence_id":"43-operating_envelope_ev_market::v141-c-R004::V::bidding.supply","source_unit_id":"43-operating_envelope_ev_market::v141-a-M03-lem::bidding.demand","target_unit_id":"43-operating_envelope_ev_market::v141-a-M03-lem::bidding.supply","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregate P2P buying and selling quantity bids under the proposed bidding strategy, in each τ. | Peer and upstream-grid selling-quantity components of each prosumer's bid in each τ. | Prosumer selling-bid submission for peer and upstream-grid trading in each τ. | Selling bids within the proposed joint buying/selling bidding optimization.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E27","v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30","v141-b-g02-E31","v141-b-g02-E33","v141-b-g03-e011"]},"active":true,"source_signature":"be328edaa3e5fb3c1465bf6136a91b15f5c71fdbb120b9a83ac6c383d90e3c95","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"ingestion_acceptance":true,"source_science":{}}],"assertion_ids":["12-p2p_microgrid_trading::v141-c-R007::E::v141-c-R007-E001","17-exogenous_cost_allocation::v141-c-R002::E::v141-c-R002-E001","43-operating_envelope_ev_market::v141-c-R004::E::v141-c-R004-E001"]});
